import { test, expect } from '@playwright/test';

test.describe('Language Preference in Profile Settings', () => {
  test.beforeEach(async ({ page }) => {
    // Navigate to the application
    await page.goto('/');

    // Login if required (assuming login is needed)
    await page.getByRole('button', { name: /sign in|login/i }).click();
    await page.getByLabel(/email|username/i).fill('testuser@example.com');
    await page.getByLabel(/password/i).fill('TestPassword123!');
    await page.getByRole('button', { name: /sign in|login/i }).click();

    // Wait for navigation to complete
    await page.waitForURL(/dashboard|home/);
  });

  test('should navigate to profile settings and display language options', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /settings|preferences/i }).click();

    // Verify we're on the settings page
    await expect(page).toHaveURL(/settings|preferences/);

    // Verify language preference section exists
    const languageSection = page.getByRole('heading', { name: /language|language preference/i });
    await expect(languageSection).toBeVisible();

    // Verify language dropdown/select is present
    const languageSelect = page.getByLabel(/language|select language/i);
    await expect(languageSelect).toBeVisible();

    // Verify multiple language options are available
    await languageSelect.click();
    const englishOption = page.getByRole('option', { name: /english/i });
    const spanishOption = page.getByRole('option', { name: /spanish|español/i });
    const frenchOption = page.getByRole('option', { name: /french|français/i });

    await expect(englishOption).toBeVisible();
    await expect(spanishOption).toBeVisible();
    await expect(frenchOption).toBeVisible();
  });

  test('should successfully change language preference to Spanish', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /settings|preferences/i }).click();

    // Get current language selection
    const languageSelect = page.getByLabel(/language|select language/i);
    const currentValue = await languageSelect.inputValue();

    // Verify current language is not Spanish
    expect(currentValue).not.toBe('es');

    // Change language to Spanish
    await languageSelect.click();
    await page.getByRole('option', { name: /spanish|español/i }).click();

    // Verify selection changed
    const updatedValue = await languageSelect.inputValue();
    expect(updatedValue).toBe('es');

    // Save settings
    const saveButton = page.getByRole('button', { name: /save|apply|confirm/i });
    await expect(saveButton).toBeVisible();
    await saveButton.click();

    // Verify success message
    const successMessage = page.getByText(/language.*updated|preference.*saved|successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify language persists after page reload
    await page.reload();
    const reloadedSelect = page.getByLabel(/language|select language/i);
    const persistedValue = await reloadedSelect.inputValue();
    expect(persistedValue).toBe('es');
  });

  test('should change language preference to French and verify UI updates', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /settings|preferences/i }).click();

    // Change language to French
    const languageSelect = page.getByLabel(/language|select language/i);
    await languageSelect.click();
    await page.getByRole('option', { name: /french|français/i }).click();

    // Save settings
    await page.getByRole('button', { name: /save|apply|confirm/i }).click();

    // Wait for success notification
    await expect(page.getByText(/language.*updated|preference.*saved|successfully/i)).toBeVisible();

    // Navigate away and back to verify persistence
    await page.getByRole('button', { name: /home|dashboard/i }).click();
    await page.waitForURL(/dashboard|home/);

    // Return to settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /settings|preferences/i }).click();

    // Verify French is still selected
    const languageSelectAfterNavigation = page.getByLabel(/language|select language/i);
    const selectedLanguage = await languageSelectAfterNavigation.inputValue();
    expect(selectedLanguage).toBe('fr');
  });

  test('should handle language preference change with unsaved changes warning', async ({ page }) => {
    // Navigate to profile settings
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /settings|preferences/i }).click();

    // Change language preference
    const languageSelect = page.getByLabel(/language|select language/i);
    await languageSelect.click();
    await page.getByRole('option', { name: /spanish|español/i }).click();

    // Try to navigate away without saving
    await page.getByRole('button', { name: /home|dashboard|back/i }).click();

    // Check for unsaved changes warning
    const warningDialog = page.getByRole('dialog');
    const warningText = page.getByText(/unsaved changes|discard|confirm/i);

    if (await warningDialog.isVisible()) {
      // If warning appears, click cancel to stay on page
      await page.getByRole('button', { name: /cancel|no|stay/i }).click();

      // Verify we're still on settings page
      await expect(page).toHaveURL(/settings|preferences/);

      // Now save the changes
      await page.getByRole('button', { name: /save|apply|confirm/i }).click();
      await expect(page.getByText(/language.*updated|preference.*saved|successfully/i)).toBeVisible();
    }
  });

  test('should display current language preference on profile page', async ({ page }) => {
    // First, set language preference to German
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /settings|preferences/i }).click();

    const languageSelect = page.getByLabel(/language|select language/i);
    await languageSelect.click();
    await page.getByRole('option', { name: /german|deutsch/i }).click();
    await page.getByRole('button', { name: /save|apply|confirm/i }).click();

    // Navigate to profile page
    await page.getByRole('button', { name: /profile|account/i }).click();
    await page.getByRole('menuitem', { name: /view profile|my profile/i }).click();

    // Verify language preference is displayed
    const languageDisplay = page.getByText(/language.*german|deutsch|german.*selected/i);
    await expect(languageDisplay).toBeVisible();
  });
});
